#include <stdio.h>


int main(void)
{
    const char *p = "aaaa";
    int pi[4] = {0};
    for (int i = 1; i < 4; i++) {
        int j = pi[i - 1];
        if (p[i] == p[j]) {
            j++;
        }
        pi[i] = j;
    }
    printf("%d\n", pi[3]);
    return 0;
}

